Lemma art_mrep_nfp_class : forall c0 a, 1 <= c0 <= 30 -> c0 <> c ->
  (rn_spb rn + c0 * 2 ^ 32 <= a < rn_spb rn + c0 * 2 ^ 32 + 2 ^ 32
   \/ 2147450880 + 8192 * rn_qs rn + c0 * 2 ^ 29 <= a < 2147450880 + 8192 * rn_qs rn + c0 * 2 ^ 29 + 2 ^ 29
